import React, { useMemo } from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';
import type { HourlyWeather } from '../hooks';

const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
  gap: ${theme.spacing.md};
`;

const Title = styled.h3`
  font-size: ${theme.typography.fontSizeMd};
  color: ${theme.colors.mainText};
  font-weight: 600;
`;

const ChartWrap = styled.div`
  width: 100%;
  overflow: hidden;
`;

const XLabels = styled.div`
  display: flex;
  justify-content: space-between;
  margin-top: ${theme.spacing.xs};
  padding: 0 4px;
`;

const XLabel = styled.span`
  font-size: 11px;
  color: ${theme.colors.mainTextMuted};
`;

const Skeleton = styled.div`
  height: 140px;
  background: ${theme.colors.border};
  border-radius: ${theme.borderRadius.md};
  animation: pulse 1.5s ease-in-out infinite;
  @keyframes pulse {
    0%, 100% { opacity: 0.4; }
    50% { opacity: 0.8; }
  }
`;

function smoothPath(pts: { x: number; y: number }[]): string {
  if (pts.length < 2) return '';
  let d = `M ${pts[0].x.toFixed(2)} ${pts[0].y.toFixed(2)}`;
  for (let i = 1; i < pts.length; i++) {
    const p = pts[i - 1];
    const c = pts[i];
    const cpx = ((p.x + c.x) / 2).toFixed(2);
    d += ` C ${cpx} ${p.y.toFixed(2)} ${cpx} ${c.y.toFixed(2)} ${c.x.toFixed(2)} ${c.y.toFixed(2)}`;
  }
  return d;
}

interface Props {
  weather: HourlyWeather | null;
  loading: boolean;
}

const W = 800;
const H = 140;
const PAD = { top: 28, bottom: 8, left: 4, right: 4 };

export default function WeatherTimeline({ weather, loading }: Props) {
  const { path, areaPath, points, tickLabels, minT, maxT } = useMemo(() => {
    if (!weather) return { path: '', areaPath: '', points: [], tickLabels: [], minT: 0, maxT: 0 };

    const temps = weather.temperature_2m;
    const times = weather.time;
    const minT = Math.min(...temps) - 2;
    const maxT = Math.max(...temps) + 2;
    const chartW = W - PAD.left - PAD.right;
    const chartH = H - PAD.top - PAD.bottom;

    const points = temps.map((t, i) => ({
      x: PAD.left + (i / (temps.length - 1)) * chartW,
      y: PAD.top + chartH - ((t - minT) / (maxT - minT)) * chartH,
      temp: Math.round(t),
    }));

    const path = smoothPath(points);
    const areaPath =
      path +
      ` L ${points[points.length - 1].x.toFixed(2)} ${(H - PAD.bottom).toFixed(2)}` +
      ` L ${points[0].x.toFixed(2)} ${(H - PAD.bottom).toFixed(2)} Z`;

    const tickIndices = [0, 6, 12, 18, 23];
    const tickLabels = tickIndices.map((i) => ({
      x: PAD.left + (i / (temps.length - 1)) * chartW,
      label: times[i] ? times[i].slice(11, 16) : '',
    }));

    return { path, areaPath, points, tickLabels, minT, maxT };
  }, [weather]);

  const tempRange = `${Math.round(minT + 2)}° – ${Math.round(maxT - 2)}°C`;

  return (
    <Wrapper>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
        <Title>24h Temperature</Title>
        {weather && <span style={{ fontSize: theme.typography.fontSizeSm, color: theme.colors.mainTextMuted }}>{tempRange}</span>}
      </div>
      {loading ? (
        <Skeleton />
      ) : (
        <ChartWrap>
          <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={H} style={{ display: 'block', overflow: 'visible' }}>
            <defs>
              <linearGradient id="tempGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#58a6ff" stopOpacity="0.35" />
                <stop offset="100%" stopColor="#58a6ff" stopOpacity="0" />
              </linearGradient>
            </defs>
            {/* Horizontal grid lines */}
            {[0.25, 0.5, 0.75].map((f) => (
              <line
                key={f}
                x1={PAD.left}
                y1={PAD.top + (H - PAD.top - PAD.bottom) * f}
                x2={W - PAD.right}
                y2={PAD.top + (H - PAD.top - PAD.bottom) * f}
                stroke={theme.colors.border}
                strokeWidth={1}
              />
            ))}
            <path d={areaPath} fill="url(#tempGrad)" />
            <path d={path} fill="none" stroke="#58a6ff" strokeWidth={2} strokeLinecap="round" />
            {/* Data points + labels at every 3 hours */}
            {points
              .filter((_, i) => i % 3 === 0)
              .map((p, i) => (
                <g key={i}>
                  <circle cx={p.x} cy={p.y} r={3} fill="#58a6ff" />
                  <text
                    x={p.x}
                    y={Math.max(PAD.top - 6, p.y - 10)}
                    textAnchor="middle"
                    fontSize={11}
                    fontWeight="600"
                    fill="#79c0ff"
                  >
                    {p.temp}°
                  </text>
                </g>
              ))}
          </svg>
          <XLabels>
            {tickLabels.map((t) => (
              <XLabel key={t.label}>{t.label}</XLabel>
            ))}
          </XLabels>
        </ChartWrap>
      )}
    </Wrapper>
  );
}
